	private PrefixMaterialization createPrefixMaterialization(PackedCostContext context) {
		int count = context.prefixRelationCount();
		int[] relationIds = new int[count];
		List<TupleExpr> factors = new ArrayList<>(count);
		Set<String> bindingNames = new LinkedHashSet<>();
		Map<String, Set<Value>> mutableFiniteValues = new LinkedHashMap<>();
		for (int ordinal = 0; ordinal < count; ordinal++) {
			int relationId = context.prefixRelationId(ordinal);
			relationIds[ordinal] = relationId;
			if (relationId <= 0 || relationId > query.relationCount()) {
				continue;
			}
			TupleExpr factor = materializeRelation(relationId);
			factors.add(factor);
			bindingNames.addAll(bindingNames(factor));
			if (factor instanceof BindingSetAssignment assignment) {
				for (BindingSet bindingSet : assignment.getBindingSets()) {
					for (String name : bindingSet.getBindingNames()) {
						Value value = bindingSet.getValue(name);
						if (value != null) {
							mutableFiniteValues.computeIfAbsent(name, ignored -> new LinkedHashSet<>()).add(value);
						}
					}
				}
			}
		}
		Map<String, Set<Value>> finiteValues;
		if (mutableFiniteValues.isEmpty()) {
			finiteValues = Map.of();
		} else {
			Map<String, Set<Value>> immutable = new LinkedHashMap<>(mutableFiniteValues.size());
			mutableFiniteValues.forEach((name, values) -> immutable.put(name, Set.copyOf(values)));
			finiteValues = Map.copyOf(immutable);
		}
		return new PrefixMaterialization(relationIds, List.copyOf(factors), Set.copyOf(bindingNames), finiteValues);
	}

	private void resizeMaterializedPrefixTable(int capacity) {
		int[] slots = new int[capacity];
		int mask = capacity - 1;
		for (int retained = 1; retained <= materializedPrefixCount; retained++) {
			int slot = PackedPrimitiveHash.slot(materializedPrefixHashes[retained], capacity);
			while (slots[slot] != 0) {
				slot = slot + 1 & mask;
			}
			slots[slot] = retained;
		}
		materializedPrefixSlots = slots;
		materializedPrefixResizeThreshold = PackedPrimitiveHash.maximumFill(capacity);
	}

