	/**
	 * Returns the packed RHS relation referenced by a pure EXISTS/NOT EXISTS filter or typed semi/anti predicate.
	 */
	public int semiAntiRightRelationId(int relationId) {
		int operator = query.relOperator(relationId);
		int condition;
		if (operator == PackedRelOp.FILTER) {
			condition = query.relPayload(relationId);
		} else if (operator == PackedRelOp.SEMI_JOIN || operator == PackedRelOp.ANTI_JOIN) {
			condition = query.payloadPrimary(semiAntiPayload(relationId));
		} else {
			throw new IllegalArgumentException("relation is not a packed semi/anti predicate");
		}
		if (query.scalarOperator(condition) == PackedScalarOp.NOT && query.scalarChildCount(condition) == 1) {
			condition = query.scalarChild(condition, 0);
		}
		return existsRightRelationId(condition);
	}

	/**
	 * Returns the packed RHS relation referenced by one {@code EXISTS} occurrence in an ordinary filter condition.
	 * Occurrences are numbered in deterministic pre-order, matching query-model materialization and visitation.
	 *
	 * @param relationId    ordinary packed filter relation
	 * @param existsOrdinal zero-based {@code EXISTS} occurrence
	 * @return referenced RHS relation, or {@code 0} when the occurrence does not exist
	 */
	public int filterExistsRightRelationId(int relationId, int existsOrdinal) {
		if (query.relOperator(relationId) != PackedRelOp.FILTER) {
			throw new IllegalArgumentException("relation is not an ordinary packed filter");
		}
		if (existsOrdinal < 0) {
			throw new IllegalArgumentException("EXISTS occurrence ordinal must be non-negative");
		}
		int[] remaining = { existsOrdinal };
		return filterExistsRightRelationId(query.relPayload(relationId), remaining);
	}

	private int filterExistsRightRelationId(int scalarId, int[] remaining) {
		if (query.scalarOperator(scalarId) == PackedScalarOp.EXISTS) {
			if (remaining[0] == 0) {
				return existsRightRelationId(scalarId);
			}
			remaining[0]--;
		}
		for (int ordinal = 0; ordinal < query.scalarChildCount(scalarId); ordinal++) {
			int rightRelationId = filterExistsRightRelationId(query.scalarChild(scalarId, ordinal), remaining);
			if (rightRelationId != 0) {
				return rightRelationId;
			}
		}
		return 0;
	}

	private int existsRightRelationId(int condition) {
		if (query.scalarOperator(condition) != PackedScalarOp.EXISTS) {
			throw new IllegalStateException("packed semi/anti condition is not EXISTS or NOT EXISTS");
		}
		int subquery = query.scalarPayload(condition);
		if (query.payloadOperator(subquery) != PackedPayloadOp.SUBQUERY_VALUE
				|| query.payloadChildCount(subquery) != 1) {
			throw new IllegalStateException("packed semi/anti condition has an invalid subquery payload");
		}
		return query.payloadChild(subquery, 0);
	}

