	public Value bindingAssignmentValue(int relationId, int rowOrdinal, String bindingName) {
		int rowId = bindingAssignmentRowId(relationId, rowOrdinal);
		for (int ordinal = 0; ordinal < bindingRowSize(rowId); ordinal++) {
			if (bindingRowName(rowId, ordinal).equals(bindingName)) {
				return bindingRowValue(rowId, ordinal);
			}
		}
		return null;
	}

